{"command":"create","path":"/workspace/codebase/rust-src/main.rs","file_text":"mod args;
mod colors;
mod ignore_files;
mod runner;

use std::io::{self, Read, Write};
use std::path::PathBuf;
use std::process;

use args::{parse_args, ArgsError, ParsedArgs};

fn main() {
    let argv: Vec<String> = std::env::args().skip(1).collect();
    match parse_args(&argv) {
        Ok(parsed) => {
            if let Err(e) = run_parsed(parsed) {
                let _ = writeln!(io::stderr(), "{}", e);
                process::exit(1);
            }
        }
        Err(ArgsError::ExitSuccess(msg)) => {
            print!("{}", msg);
            if !msg.ends_with('\n') {
                println!();
            }
            process::exit(0);
        }
        Err(ArgsError::ExitFailure(msg)) => {
            eprint!("{}", msg);
            if !msg.ends_with('\n') {
                eprintln!();
            }
            process::exit(1);
        }
    }
}

fn run_parsed(parsed: ParsedArgs) -> Result<(), String> {
    let paths = if parsed.options.stdin {
        let mut buffer = String::new();
        io::stdin()
            .read_to_string(&mut buffer)
            .map_err(|e| e.to_string())?;
        buffer
            .split('\n')
            .filter(|s| !s.is_empty())
            .map(|s| s.to_string())
            .collect::<Vec<_>>()
    } else {
        parsed.positional
    };

    if paths.is_empty() && !parsed.options.stdin {
        return Err(
            "Error: You have to provide at least one file/directory to transform.".into(),
        );
    }

    // Resolve transform path unless URL
    let transform = parsed.options.transform.clone();
    let transform_path = if transform.starts_with("http://") || transform.starts_with("https://") {
        transform
    } else {
        PathBuf::from(&transform)
            .canonicalize()
            .unwrap_or_else(|_| {
                // match Node path.resolve behavior for non-existing files
                std::env::current_dir()
                    .unwrap_or_else(|_| PathBuf::from("."))
                    .join(&transform)
            })
            .to_string_lossy()
            .to_string()
    };

    runner::run(&transform_path, &paths, &parsed.options)
}"}

{"command":"create","path":"/workspace/codebase/rust-src/args.rs","file_text":"use serde_json::Value;
use std::collections::HashMap;
use std::fs;
use std::path::Path;

#[derive(Debug, Clone)]
pub struct Options {
    pub transform: String,
    pub cpus: Option<usize>,
    pub verbose: u8,
    pub dry: bool,
    pub print: bool,
    pub babel: bool,
    pub extensions: String,
    pub ignore_pattern: Vec<String>,
    pub ignore_config: Vec<String>,
    pub gitignore: bool,
    pub run_in_band: bool,
    pub silent: bool,
    pub parser: String,
    pub parser_config: Option<Value>,
    pub fail_on_error: bool,
    pub stdin: bool,
    /// Unknown / passthrough options forwarded to the transform
    pub extra: HashMap<String, Value>,
}

#[derive(Debug)]
pub struct ParsedArgs {
    pub options: Options,
    pub positional: Vec<String>,
}

#[derive(Debug)]
pub enum ArgsError {
    ExitSuccess(String),
    ExitFailure(String),
}

fn default_extensions() -> String {
    // Mirrors @babel/core DEFAULT_EXTENSIONS + ts,tsx, sorted, without leading dots
    // DEFAULT_EXTENSIONS: .js, .jsx, .es6, .es, .mjs, .cjs
    let mut exts = vec![
        "js", "jsx", "es6", "es", "mjs", "cjs", "ts", "tsx",
    ];
    exts.sort();
    exts.join(",")
}

fn help_text() -> String {
    let def_ext = default_extensions();
    format!(
        r#"Usage: jscodeshift [OPTION]... PATH...
  or:  jscodeshift [OPTION]... -t TRANSFORM_PATH PATH...
  or:  jscodeshift [OPTION]... -t URL PATH...
  or:  jscodeshift [OPTION]... --stdin < file_list.txt

Apply transform logic in TRANSFORM_PATH (recursively) to every PATH.
If --stdin is set, each line of the standard input is used as a path.

Options:
"..." behind an option means that it can be supplied multiple times.
All options are also passed to the transformer, which means you can supply custom options that are not listed here.

      --(no-)babel              apply babeljs to the transform file
                                (default: true)
  -c, --cpus=N                  start at most N child processes to process source files
                                (default: max(all - 1, 1))
  -d, --(no-)dry                dry run (no changes are made to files)
                                (default: false)
      --extensions=EXT          transform files with these file extensions (comma separated list)
                                (default: {def_ext})
      --fail-on-error           Return a non-zero code when there are errors
                                (default: false)
      --(no-)gitignore          adds entries the current directory's .gitignore file
                                (default: false)
  -h, --help                    print this help and exit
      --ignore-config=FILE ...  ignore files if they match patterns sourced from a configuration file (e.g. a .gitignore)
      --ignore-pattern=GLOB ...  ignore files that match a provided glob expression
      --parser=babel|babylon|flow|ts|tsx  the parser to use for parsing the source files
                                          (default: babel)
      --parser-config=FILE      path to a JSON file containing a custom parser configuration for flow or babylon
  -p, --(no-)print              print transformed files to stdout, useful for development
                                (default: false)
      --(no-)run-in-band        run serially in the current process
                                (default: false)
  -s, --(no-)silent             do not write to stdout or stderr
                                (default: false)
      --(no-)stdin              read file/directory list from stdin
                                (default: false)
  -t, --transform=FILE          path to the transform file. Can be either a local path or url
                                (default: ./transform.js)
  -v, --verbose=0|1|2           show more information about the transform process
                                (default: 0)
      --version                 print version and exit
"#
    )
}

fn is_option(value: &str) -> bool {
    value.starts_with('-') && value != "-"
}

fn process_json_or_string(value: &str) -> Value {
    if let Ok(v) = serde_json::from_str::<Value>(value) {
        v
    } else {
        Value::String(value.to_string())
    }
}

fn version_text() -> String {
    // Mirror JS version output structure; resolve package versions via node when possible
    let pkg_version = env!("CARGO_PKG_VERSION");
    let script = r#"
const path = require('path');
function reqPkg(name) {
  try {
    const entry = require.resolve(name);
    let dir = path.dirname(entry);
    while (dir !== '/') {
      try {
        const pkg = require(path.join(dir, 'package.json'));
        if (pkg.name === name) return pkg.version || '';
      } catch (e) {}
      dir = path.dirname(dir);
    }
  } catch (e) {}
  return '';
}
let babel = '', babylon = '', flow = '', recast = '';
try { babel = require('@babel/core').version || ''; } catch(e) {}
babylon = reqPkg('@babel/parser');
flow = reqPkg('flow-parser');
recast = reqPkg('recast');
process.stdout.write([babel, babylon, flow, recast].join('\n'));
"#;
    let versions = std::process::Command::new("node")
        .arg("-e")
        .arg(script)
        .current_dir(
            Path::new(env!("CARGO_MANIFEST_DIR")),
        )
        .output()
        .ok()
        .and_then(|o| {
            if o.status.success() {
                Some(String::from_utf8_lossy(&o.stdout).to_string())
            } else {
                None
            }
        })
        .unwrap_or_default();
    let parts: Vec<&str> = versions.lines().collect();
    let babel = parts.first().copied().unwrap_or("");
    let babylon = parts.get(1).copied().unwrap_or("");
    let flow = parts.get(2).copied().unwrap_or("");
    let recast = parts.get(3).copied().unwrap_or("");
    format!(
        "jscodeshift: {pkg_version}\n - babel: {babel}\n - babylon: {babylon}\n - flow: {flow}\n - recast: {recast}\n"
    )
}

pub fn parse_args(args: &[String]) -> Result<ParsedArgs, ArgsError> {
    let mut options = Options {
        transform: "./transform.js".into(),
        cpus: None,
        verbose: 0,
        dry: false,
        print: false,
        babel: true,
        extensions: default_extensions(),
        ignore_pattern: vec![],
        ignore_config: vec![],
        gitignore: false,
        run_in_band: false,
        silent: false,
        parser: "babel".into(),
        parser_config: None,
        fail_on_error: false,
        stdin: false,
        extra: HashMap::new(),
    };

    let mut positional = Vec::new();
    let mut i = 0usize;

    while i < args.len() {
        let arg = &args[i];
        if is_option(arg) {
            let mut option_name = arg.as_str();
            let mut value: Option<String> = None;
            if let Some(idx) = arg.find('=') {
                option_name = &arg[..idx];
                value = Some(arg[idx + 1..].to_string());
            }

            // Built-in options
            match option_name {
                "-h" | "--help" => {
                    return Err(ArgsError::ExitSuccess(help_text()));
                }
                "--version" => {
                    return Err(ArgsError::ExitSuccess(version_text()));
                }
                "-t" | "--transform" => {
                    let v = take_value(&mut i, args, value, "transform")?;
                    options.transform = v;
                }
                "-c" | "--cpus" => {
                    let v = take_value(&mut i, args, value, "cpus")?;
                    options.cpus = Some(v.parse::<usize>().unwrap_or(0));
                }
                "-v" | "--verbose" => {
                    let v = take_value(&mut i, args, value, "verbose")?;
                    let n: u8 = v.parse().unwrap_or(0);
                    if n > 2 {
                        return Err(ArgsError::ExitFailure(format!(
                            "Error: --verbose must be one of the values 0,1,2\n\n---\n\n{}",
                            help_text()
                        )));
                    }
                    options.verbose = n;
                }
                "-d" | "--dry" => {
                    options.dry = flag_value(option_name, value);
                }
                "--no-dry" => {
                    options.dry = false;
                }
                "-p" | "--print" => {
                    options.print = flag_value(option_name, value);
                }
                "--no-print" => {
                    options.print = false;
                }
                "--babel" => {
                    options.babel = flag_value(option_name, value);
                }
                "--no-babel" => {
                    options.babel = false;
                }
                "--extensions" => {
                    let v = take_value(&mut i, args, value, "extensions")?;
                    options.extensions = v;
                }
                "--ignore-pattern" => {
                    let v = take_value(&mut i, args, value, "ignore-pattern")?;
                    options.ignore_pattern.push(v);
                }
                "--ignore-config" => {
                    let v = take_value(&mut i, args, value, "ignore-config")?;
                    options.ignore_config.push(v);
                }
                "--gitignore" => {
                    options.gitignore = flag_value(option_name, value);
                }
                "--no-gitignore" => {
                    options.gitignore = false;
                }
                "--run-in-band" => {
                    options.run_in_band = flag_value(option_name, value);
                }
                "--no-run-in-band" => {
                    options.run_in_band = false;
                }
                "-s" | "--silent" => {
                    options.silent = flag_value(option_name, value);
                }
                "--no-silent" => {
                    options.silent = false;
                }
                "--parser" => {
                    let v = take_value(&mut i, args, value, "parser")?;
                    let allowed = ["babel", "babylon", "flow", "ts", "tsx"];
                    if !allowed.contains(&v.as_str()) {
                        return Err(ArgsError::ExitFailure(format!(
                            "Error: --parser must be one of the values {}\n\n---\n\n{}",
                            allowed.join(","),
                            help_text()
                        )));
                    }
                    options.parser = v;
                }
                "--parser-config" => {
                    let v = take_value(&mut i, args, value, "parser-config")?;
                    let content = fs::read_to_string(&v).map_err(|e| {
                        ArgsError::ExitFailure(format!("Error reading parser-config: {e}"))
                    })?;
                    let json: Value = serde_json::from_str(&content).map_err(|e| {
                        ArgsError::ExitFailure(format!("Error parsing parser-config JSON: {e}"))
                    })?;
                    options.parser_config = Some(json);
                }
                "--fail-on-error" => {
                    options.fail_on_error = flag_value(option_name, value);
                }
                "--no-fail-on-error" => {
                    options.fail_on_error = false;
                }
                "--stdin" => {
                    options.stdin = flag_value(option_name, value);
                }
                "--no-stdin" => {
                    options.stdin = false;
                }
                other => {
                    // Unknown options are passed along (nomnom-compatible)
                    let real_name = other
                        .trim_start_matches('-')
                        .trim_start_matches("no-")
                        .to_string();
                    let is_no = other.starts_with("--no-");

                    if is_no {
                        options.extra.insert(real_name, Value::Bool(false));
                    } else {
                        let next_is_option = i + 1 < args.len() && is_option(&args[i + 1]);
                        let val = if let Some(v) = value {
                            Some(v)
                        } else if !next_is_option && i + 1 < args.len() {
                            i += 1;
                            Some(args[i].clone())
                        } else {
                            None
                        };

                        if let Some(v) = val {
                            let processed = process_json_or_string(&v);
                            if let Some(existing) = options.extra.get_mut(&real_name) {
                                match existing {
                                    Value::Array(arr) => arr.push(processed),
                                    Value::Bool(true) => {
                                        *existing = Value::Array(vec![processed]);
                                    }
                                    other_val => {
                                        let prev = other_val.clone();
                                        *existing = Value::Array(vec![prev, processed]);
                                    }
                                }
                            } else {
                                options.extra.insert(real_name, processed);
                            }
                        } else {
                            options.extra.insert(real_name, Value::Bool(true));
                        }
                    }
                }
            }
        } else {
            // positional
            if arg.chars().all(|c| c.is_ascii_digit()) && !arg.is_empty() {
                // JS converts pure digit args to Number; we keep as string for paths
                // but preserve numeric representation in extra if needed. Paths stay strings.
                positional.push(arg.clone());
            } else {
                positional.push(arg.clone());
            }
        }
        i += 1;
    }

    if positional.is_empty() && !options.stdin {
        return Err(ArgsError::ExitFailure(format!(
            "Error: You have to provide at least one file/directory to transform.\n\n---\n\n{}",
            help_text()
        )));
    }

    Ok(ParsedArgs { options, positional })
}

fn flag_value(option_name: &str, value: Option<String>) -> bool {
    if option_name.starts_with("--no-") {
        false
    } else if let Some(v) = value {
        v == "1"
    } else {
        true
    }
}

fn take_value(
    i: &mut usize,
    args: &[String],
    value: Option<String>,
    name: &str,
) -> Result<String, ArgsError> {
    if let Some(v) = value {
        return Ok(v);
    }
    if *i + 1 < args.len() && !is_option(&args[*i + 1]) {
        *i += 1;
        return Ok(args[*i].clone());
    }
    Err(ArgsError::ExitFailure(format!(
        "Missing value: --{name} requires a value\n\n---\n\n{}",
        help_text()
    )))
}

impl Options {
    /// Serialize options to JSON for the worker bridge.
    pub fn to_json(&self) -> Value {
        let mut map = serde_json::Map::new();
        map.insert("transform".into(), Value::String(self.transform.clone()));
        if let Some(c) = self.cpus {
            map.insert("cpus".into(), Value::Number(c.into()));
        }
        map.insert("verbose".into(), Value::Number(self.verbose.into()));
        map.insert("dry".into(), Value::Bool(self.dry));
        map.insert("print".into(), Value::Bool(self.print));
        map.insert("babel".into(), Value::Bool(self.babel));
        map.insert("extensions".into(), Value::String(self.extensions.clone()));
        map.insert(
            "ignorePattern".into(),
            Value::Array(
                self.ignore_pattern
                    .iter()
                    .map(|s| Value::String(s.clone()))
                    .collect(),
            ),
        );
        map.insert(
            "ignoreConfig".into(),
            Value::Array(
                self.ignore_config
                    .iter()
                    .map(|s| Value::String(s.clone()))
                    .collect(),
            ),
        );
        map.insert("gitignore".into(), Value::Bool(self.gitignore));
        map.insert("runInBand".into(), Value::Bool(self.run_in_band));
        map.insert("silent".into(), Value::Bool(self.silent));
        map.insert("parser".into(), Value::String(self.parser.clone()));
        if let Some(ref pc) = self.parser_config {
            map.insert("parserConfig".into(), pc.clone());
        }
        map.insert("failOnError".into(), Value::Bool(self.fail_on_error));
        map.insert("stdin".into(), Value::Bool(self.stdin));
        for (k, v) in &self.extra {
            map.insert(k.clone(), v.clone());
        }
        Value::Object(map)
    }
}"}

{"command":"create","path":"/workspace/codebase/rust-src/colors.rs","file_text":"//! Minimal ANSI color helpers matching picocolors behavior when TTY is attached.

fn enabled() -> bool {
    // picocolors disables colors when NO_COLOR is set or not a TTY
    if std::env::var_os("NO_COLOR").is_some() {
        return false;
    }
    atty_stdout()
}

fn atty_stdout() -> bool {
    // Simple isatty check via libc-free heuristic: check /dev/stdout
    #[cfg(unix)]
    {
        use std::os::unix::io::AsRawFd;
        unsafe { libc_isatty(std::io::stdout().as_raw_fd()) }
    }
    #[cfg(not(unix))]
    {
        true
    }
}

#[cfg(unix)]
fn libc_isatty(fd: i32) -> bool {
    // Use nix-less approach via std::process or just always color for simplicity
    // Actually check using ioctl-free: readlink /proc/self/fd/N
    let path = format!("/proc/self/fd/{fd}");
    if let Ok(meta) = std::fs::symlink_metadata(&path) {
        // If it's a character device it's likely a tty
        use std::os::unix::fs::FileTypeExt;
        return meta.file_type().is_char_device();
    }
    false
}

pub fn bg_green(s: &str) -> String {
    if enabled() {
        format!("\x1b[42m{s}\x1b[49m")
    } else {
        s.to_string()
    }
}
pub fn bg_yellow(s: &str) -> String {
    if enabled() {
        format!("\x1b[43m{s}\x1b[49m")
    } else {
        s.to_string()
    }
}
pub fn bg_red(s: &str) -> String {
    if enabled() {
        format!("\x1b[41m{s}\x1b[49m")
    } else {
        s.to_string()
    }
}
pub fn bg_blue(s: &str) -> String {
    if enabled() {
        format!("\x1b[44m{s}\x1b[49m")
    } else {
        s.to_string()
    }
}
pub fn white(s: &str) -> String {
    if enabled() {
        format!("\x1b[37m{s}\x1b[39m")
    } else {
        s.to_string()
    }
}
pub fn red(s: &str) -> String {
    if enabled() {
        format!("\x1b[31m{s}\x1b[39m")
    } else {
        s.to_string()
    }
}
pub fn yellow(s: &str) -> String {
    if enabled() {
        format!("\x1b[33m{s}\x1b[39m")
    } else {
        s.to_string()
    }
}
pub fn green(s: &str) -> String {
    if enabled() {
        format!("\x1b[32m{s}\x1b[39m")
    } else {
        s.to_string()
    }
}
pub fn blue(s: &str) -> String {
    if enabled() {
        format!("\x1b[34m{s}\x1b[39m")
    } else {
        s.to_string()
    }
}

pub fn ok_tag() -> String {
    bg_green(&white(" OKK "))
}
pub fn noc_tag() -> String {
    bg_yellow(&white(" NOC "))
}
pub fn skip_tag() -> String {
    bg_yellow(&white(" SKIP "))
}
pub fn err_tag() -> String {
    bg_red(&white(" ERR "))
}
pub fn rep_tag() -> String {
    bg_blue(&white(" REP "))
}
pub fn error_tag() -> String {
    bg_red(&white("ERROR"))
}"}

{"command":"create","path":"/workspace/codebase/rust-src/ignore_files.rs","file_text":"//! Ignore pattern handling matching jscodeshift's ignoreFiles.js (picomatch-based).

use globset::{Glob, GlobSet, GlobSetBuilder};
use std::fs;
use std::path::Path;
use std::sync::Mutex;

pub struct IgnoreSet {
    patterns: Mutex<Vec<String>>,
}

impl IgnoreSet {
    pub fn new() -> Self {
        Self {
            patterns: Mutex::new(Vec::new()),
        }
    }

    pub fn add_from_input(&self, input: &[String]) {
        for p in input {
            self.add_ignore_pattern(p);
        }
    }

    pub fn add_from_file(&self, input: &[String]) {
        for config in input {
            let path = Path::new(config);
            if path.is_file() {
                if let Ok(content) = fs::read_to_string(path) {
                    for line in content.split('\n') {
                        let line = line.trim_end_matches('\r');
                        self.add_ignore_pattern(line);
                    }
                }
            }
        }
    }

    fn add_ignore_pattern(&self, val: &str) {
        if val.is_empty() || val.starts_with('#') {
            return;
        }
        let pattern = val.to_string();
        let mut matchers = self.patterns.lock().unwrap();
        if !pattern.contains('/') {
            matchers.push(format!("**/{pattern}"));
        } else if pattern.ends_with('/') {
            matchers.push(format!("**/{pattern}**"));
            matchers.push(format!("{pattern}**"));
        }
        matchers.push(pattern);
    }

    pub fn should_ignore(&self, path: &str) -> bool {
        let matchers = self.patterns.lock().unwrap();
        if matchers.is_empty() {
            return false;
        }
        let set = build_globset(&matchers);
        if set.is_match(path) {
            return true;
        }
        // Strip leading ./ or ../ traversal prefixes
        let normalized = strip_traversal(path);
        if normalized != path {
            return set.is_match(normalized);
        }
        false
    }
}

fn strip_traversal(path: &str) -> &str {
    let mut p = path;
    loop {
        if let Some(rest) = p.strip_prefix("../") {
            p = rest;
            continue;
        }
        if let Some(rest) = p.strip_prefix("..\\") {
            p = rest;
            continue;
        }
        if let Some(rest) = p.strip_prefix("./") {
            p = rest;
            continue;
        }
        if let Some(rest) = p.strip_prefix(".\\") {
            p = rest;
            continue;
        }
        break;
    }
    p
}

fn build_globset(patterns: &[String]) -> GlobSet {
    let mut builder = GlobSetBuilder::new();
    for p in patterns {
        // picomatch with dot:true — enable matching dotfiles
        if let Ok(g) = Glob::new(p) {
            builder.add(g);
        } else {
            // Try escaping less strictly
            let _ = Glob::new(&format!("*{p}*")).map(|g| builder.add(g));
        }
    }
    builder.build().unwrap_or_else(|_| GlobSetBuilder::new().build().unwrap())
}

impl Default for IgnoreSet {
    fn default() -> Self {
        Self::new()
    }
}"}

