//! Transform execution is delegated to the Node.js bridge (bridge/transform-host.js).

use crate::args::Options;
use crate::colors;
use crate::ignore_files::IgnoreSet;
use serde::Deserialize;
use serde_json::{json, Value};
use std::collections::HashMap;
use std::fs;
use std::io::{BufRead, BufReader, Write};
use std::path::{Path, PathBuf};
use std::process::{Command, Stdio};
use std::sync::atomic::{AtomicUsize, Ordering};
use std::sync::{Arc, Mutex};
use std::time::Instant;
use walkdir::WalkDir;

const CHUNK_SIZE: usize = 50;

fn package_root() -> PathBuf {
    PathBuf::from(env!("CARGO_MANIFEST_DIR"))
}

fn line_break(s: &str) -> String {
    if s.ends_with('\n') {
        s.to_string()
    } else {
        format!("{s}\n")
    }
}

fn log_status(status: &str, msg: &str, verbose: u8) {
    match status {
        "ok" if verbose >= 2 => {
            print!("{}{}", colors::ok_tag(), msg);
        }
        "nochange" if verbose >= 1 => {
            print!("{}{}", colors::noc_tag(), msg);
        }
        "skip" if verbose >= 1 => {
            print!("{}{}", colors::skip_tag(), msg);
        }
        "error" if verbose >= 0 => {
            // verbose is u8, always >= 0
            print!("{}{}", colors::err_tag(), msg);
        }
        _ => {}
    }
}

fn report(file: &str, msg: &str) {
    print!(
        "{}",
        line_break(&format!("{}{} {}", colors::rep_tag(), file, msg))
    );
}

fn show_file_stats(error: usize, nochange: usize, skip: usize, ok: usize) {
    print!(
        "Results: \n{}{}{}{}",
        colors::red(&format!("{error} errors\n")),
        colors::yellow(&format!("{nochange} unmodified\n")),
        colors::yellow(&format!("{skip} skipped\n")),
        colors::green(&format!("{ok} ok\n")),
    );
}

fn show_stats(stats: &HashMap<String, i64>) {
    let mut names: Vec<_> = stats.keys().cloned().collect();
    names.sort();
    if !names.is_empty() {
        print!("{}", colors::blue("Stats: \n"));
    }
    for name in names {
        println!("{}: {}", name, stats[&name]);
    }
}

fn get_all_files(paths: &[String], extensions: Option<&[String]>, ignores: &IgnoreSet) -> Vec<String> {
    let mut result = Vec::new();
    for file in paths {
        let path = Path::new(file);
        let meta = match fs::symlink_metadata(path) {
            Ok(m) => m,
            Err(_) => {
                eprint!("Skipping path {file} which does not exist. \n");
                continue;
            }
        };
        if meta.is_dir() {
            // Walk directory
            for entry in WalkDir::new(path).into_iter().filter_map(|e| e.ok()) {
                let p = entry.path();
                let name = p.to_string_lossy().to_string();
                // Match JS: directories get trailing slash treatment for ignore; we check path as-is
                if entry.file_type().is_dir() {
                    if ignores.should_ignore(&name) || ignores.should_ignore(&format!("{name}/")) {
                        // skip subtree — WalkDir doesn't easily support; check each file
                        continue;
                    }
                    continue;
                }
                if ignores.should_ignore(&name) {
                    continue;
                }
                if let Some(exts) = extensions {
                    let ext = p
                        .extension()
                        .and_then(|e| e.to_str())
                        .map(|e| format!(".{e}"))
                        .unwrap_or_default();
                    if !exts.iter().any(|e| e == &ext) {
                        continue;
                    }
                }
                // Also skip if any parent directory is ignored
                let mut skip = false;
                for ancestor in p.ancestors().skip(1) {
                    let a = ancestor.to_string_lossy().to_string();
                    if ignores.should_ignore(&a) || ignores.should_ignore(&format!("{a}/")) {
                        skip = true;
                        break;
                    }
                }
                if !skip {
                    result.push(name);
                }
            }
        } else {
            // single file
            let name = file.clone();
            let ext_ok = if let Some(exts) = extensions {
                let ext = path
                    .extension()
                    .and_then(|e| e.to_str())
                    .map(|e| format!(".{e}"))
                    .unwrap_or_default();
                exts.iter().any(|e| e == &ext)
            } else {
                true
            };
            if ext_ok && !ignores.should_ignore(&name) {
                result.push(name);
            }
        }
    }
    result
}

fn download_transform(url: &str) -> Result<PathBuf, String> {
    let response = ureq::get(url)
        .call()
        .map_err(|e| format!("Failed to download transform: {e}"))?;
    let mut body = Vec::new();
    response
        .into_reader()
        .read_to_end(&mut body)
        .map_err(|e| e.to_string())?;
    let ext = Path::new(url)
        .extension()
        .and_then(|e| e.to_str())
        .unwrap_or("js");
    let tmp = tempfile::Builder::new()
        .prefix("jscodeshift")
        .suffix(&format!(".{ext}"))
        .tempfile()
        .map_err(|e| e.to_string())?;
    let (mut file, path) = tmp.keep().map_err(|e| e.error.to_string())?;
    file.write_all(&body).map_err(|e| e.to_string())?;
    Ok(path)
}

#[derive(Debug, Deserialize)]
struct WorkerMessage {
    action: String,
    #[serde(default)]
    status: Option<String>,
    #[serde(default)]
    msg: Option<String>,
    #[serde(default)]
    name: Option<String>,
    #[serde(default)]
    quantity: Option<i64>,
    #[serde(default)]
    file: Option<String>,
}

pub fn run(transform_file: &str, paths: &[String], options: &Options) -> Result<(), String> {
    let available_cpus = num_cpus::get().saturating_sub(1).max(1);
    let cpus = options
        .cpus
        .map(|c| c.min(available_cpus))
        .unwrap_or(available_cpus);

    let extensions: Option<Vec<String>> = if options.extensions.is_empty() {
        None
    } else {
        Some(
            options
                .extensions
                .split(',')
                .map(|ext| format!(".{}", ext.trim()))
                .collect(),
        )
    };

    let ignores = IgnoreSet::new();
    ignores.add_from_input(&options.ignore_pattern);
    ignores.add_from_file(&options.ignore_config);
    if options.gitignore {
        let gi = std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("."))
            .join(".gitignore");
        ignores.add_from_file(&[gi.to_string_lossy().to_string()]);
    }

    let transform_path = if transform_file.starts_with("http://")
        || transform_file.starts_with("https://")
    {
        download_transform(transform_file)?
    } else {
        let p = PathBuf::from(transform_file);
        if !p.exists() {
            eprint!(
                "{} Transform file {} does not exist \n",
                colors::error_tag(),
                transform_file
            );
            return Ok(());
        }
        p
    };

    let files = get_all_files(paths, extensions.as_deref(), &ignores);
    let num_files = files.len();

    if num_files == 0 {
        print!("No files selected, nothing to do. \n");
        return Ok(());
    }

    let processes = if options.run_in_band {
        1
    } else {
        num_files.min(cpus)
    };
    let chunk_size = if processes > 1 {
        ((num_files + processes - 1) / processes).min(CHUNK_SIZE)
    } else {
        num_files
    };

    if !options.silent {
        print!("Processing {num_files} files... \n");
        if !options.run_in_band {
            print!("Spawning {processes} workers...\n");
        }
        if options.dry {
            print!(
                "{}",
                colors::green("Running in dry mode, no files will be written! \n")
            );
        }
    }

    let start = Instant::now();
    let file_error = Arc::new(AtomicUsize::new(0));
    let file_ok = Arc::new(AtomicUsize::new(0));
    let file_nochange = Arc::new(AtomicUsize::new(0));
    let file_skip = Arc::new(AtomicUsize::new(0));
    let stats_counter: Arc<Mutex<HashMap<String, i64>>> = Arc::new(Mutex::new(HashMap::new()));

    let next_index = Arc::new(AtomicUsize::new(0));
    let files = Arc::new(files);
    let options_json = options.to_json();
    let babel_flag = if options.babel { "babel" } else { "no-babel" };
    let bridge_script = package_root().join("bridge/transform-host.js");
    let transform_str = transform_path.to_string_lossy().to_string();
    let silent = options.silent;
    let verbose = options.verbose;
    let run_in_band = options.run_in_band;

    let mut handles = Vec::new();

    for _ in 0..processes {
        let next_index = Arc::clone(&next_index);
        let files = Arc::clone(&files);
        let file_error = Arc::clone(&file_error);
        let file_ok = Arc::clone(&file_ok);
        let file_nochange = Arc::clone(&file_nochange);
        let file_skip = Arc::clone(&file_skip);
        let stats_counter = Arc::clone(&stats_counter);
        let options_json = options_json.clone();
        let bridge_script = bridge_script.clone();
        let transform_str = transform_str.clone();
        let babel_flag = babel_flag.to_string();

        let handle = std::thread::spawn(move || {
            worker_loop(
                &bridge_script,
                &transform_str,
                &babel_flag,
                &files,
                chunk_size,
                &next_index,
                &options_json,
                &file_error,
                &file_ok,
                &file_nochange,
                &file_skip,
                &stats_counter,
                silent,
                verbose,
                run_in_band,
            );
        });
        handles.push(handle);
    }

    for h in handles {
        let _ = h.join();
    }

    let elapsed = start.elapsed().as_secs_f64();
    let time_elapsed = format!("{:.3}", elapsed);

    if !options.silent {
        print!("All done. \n");
        show_file_stats(
            file_error.load(Ordering::SeqCst),
            file_nochange.load(Ordering::SeqCst),
            file_skip.load(Ordering::SeqCst),
            file_ok.load(Ordering::SeqCst),
        );
        let stats = stats_counter.lock().unwrap();
        show_stats(&stats);
        print!("Time elapsed: {time_elapsed}seconds \n");

        if options.fail_on_error && file_error.load(Ordering::SeqCst) > 0 {
            std::process::exit(1);
        }
    }

    Ok(())
}

fn worker_loop(
    bridge_script: &Path,
    transform_str: &str,
    babel_flag: &str,
    files: &[String],
    chunk_size: usize,
    next_index: &AtomicUsize,
    options_json: &Value,
    file_error: &AtomicUsize,
    file_ok: &AtomicUsize,
    file_nochange: &AtomicUsize,
    file_skip: &AtomicUsize,
    stats_counter: &Mutex<HashMap<String, i64>>,
    silent: bool,
    verbose: u8,
    run_in_band: bool,
) {
    // Spawn a persistent node worker
    let mut child = match Command::new("node")
        .arg(bridge_script)
        .arg(transform_str)
        .arg(babel_flag)
        .stdin(Stdio::piped())
        .stdout(Stdio::piped())
        .stderr(Stdio::inherit())
        .spawn()
    {
        Ok(c) => c,
        Err(e) => {
            eprintln!("Failed to spawn worker: {e}");
            return;
        }
    };

    let mut stdin = child.stdin.take().expect("stdin");
    let stdout = child.stdout.take().expect("stdout");
    let mut reader = BufReader::new(stdout);

    loop {
        let start = next_index.fetch_add(chunk_size, Ordering::SeqCst);
        if start >= files.len() {
            // signal end
            let _ = writeln!(stdin, "{}", json!({"action": "end"}));
            let _ = stdin.flush();
            break;
        }
        let end = (start + chunk_size).min(files.len());
        let chunk: Vec<String> = files[start..end].to_vec();

        if !silent && !run_in_band {
            print!(
                "Sending {} files to free worker...\n",
                chunk.len()
            );
            let _ = std::io::stdout().flush();
        }

        let msg = json!({
            "action": "run",
            "files": chunk,
            "options": options_json,
        });
        if writeln!(stdin, "{msg}").is_err() {
            break;
        }
        if stdin.flush().is_err() {
            break;
        }

        // Read messages until we get "free" or "done"
        loop {
            let mut line = String::new();
            match reader.read_line(&mut line) {
                Ok(0) => return, // EOF
                Ok(_) => {}
                Err(_) => return,
            }
            let line = line.trim();
            if line.is_empty() {
                continue;
            }
            let msg: WorkerMessage = match serde_json::from_str(line) {
                Ok(m) => m,
                Err(_) => continue,
            };
            match msg.action.as_str() {
                "status" => {
                    let status = msg.status.as_deref().unwrap_or("error");
                    let m = line_break(msg.msg.as_deref().unwrap_or(""));
                    match status {
                        "ok" => {
                            file_ok.fetch_add(1, Ordering::SeqCst);
                        }
                        "nochange" => {
                            file_nochange.fetch_add(1, Ordering::SeqCst);
                        }
                        "skip" => {
                            file_skip.fetch_add(1, Ordering::SeqCst);
                        }
                        "error" => {
                            file_error.fetch_add(1, Ordering::SeqCst);
                        }
                        _ => {}
                    }
                    if !silent {
                        log_status(status, &m, verbose);
                        let _ = std::io::stdout().flush();
                    }
                }
                "update" => {
                    if let Some(name) = msg.name {
                        let qty = msg.quantity.unwrap_or(1);
                        let mut stats = stats_counter.lock().unwrap();
                        *stats.entry(name).or_insert(0) += qty;
                    }
                }
                "report" => {
                    if !silent {
                        report(
                            msg.file.as_deref().unwrap_or(""),
                            msg.msg.as_deref().unwrap_or(""),
                        );
                        let _ = std::io::stdout().flush();
                    }
                }
                "free" | "done" => {
                    break;
                }
                _ => {}
            }
        }
    }

    let _ = child.wait();
}"}

