/**
 * Minimal Node.js compatibility bridge for executing jscodeshift transforms.
 * Spawned by the Rust runner. Speaks JSON-lines over stdin/stdout.
 *
 * Protocol:
 *   stdin  <- { "action": "run", "files": [...], "options": {...} }
 *   stdin  <- { "action": "end" }
 *   stdout -> { "action": "status", "status": "ok|nochange|skip|error", "msg": "..." }
 *   stdout -> { "action": "update", "name": "...", "quantity": N }
 *   stdout -> { "action": "report", "file": "...", "msg": "..." }
 *   stdout -> { "action": "free" }
 */
'use strict';

const path = require('path');
const fs = require('graceful-fs');
const writeFileAtomic = require('write-file-atomic');
const { DEFAULT_EXTENSIONS } = require('@babel/core');

// Resolve core from bridge/src (migrated library sources)
const getParser = require('./src/getParser');
const jscodeshift = require('./src/core');

let presetEnv;
try {
  presetEnv = require('@babel/preset-env');
} catch (_) {}

const transformFile = process.argv[2];
const babelFlag = process.argv[3]; // 'babel' | 'no-babel'

let transform;
let parserFromTransform;

function setup(tr, babel) {
  if (babel === 'babel') {
    const presets = [];
    if (presetEnv) {
      presets.push([
        presetEnv.default,
        { targets: { node: true } },
      ]);
    }
    presets.push(
      /\.tsx?$/.test(tr)
        ? require('@babel/preset-typescript').default
        : require('@babel/preset-flow').default
    );

    require('@babel/register')({
      configFile: false,
      babelrc: false,
      presets,
      plugins: [
        require('@babel/plugin-transform-class-properties').default,
        require('@babel/plugin-transform-nullish-coalescing-operator').default,
        require('@babel/plugin-transform-optional-chaining').default,
        require('@babel/plugin-transform-modules-commonjs').default,
        require('@babel/plugin-transform-private-methods').default,
      ],
      extensions: [...DEFAULT_EXTENSIONS, '.ts', '.tsx'],
      ignore: [
        /@babel\/parser/,
        /\/flow-parser\//,
        /\/recast\//,
        /\/ast-types\//,
      ],
    });
  }

  const mod = require(tr);
  transform = typeof mod.default === 'function' ? mod.default : mod;
  if (mod.parser) {
    parserFromTransform =
      typeof mod.parser === 'string' ? getParser(mod.parser) : mod.parser;
  }
}

function prepareJscodeshift(options) {
  const parser = parserFromTransform || getParser(options.parser, options.parserConfig);
  return jscodeshift.withParser(parser);
}

function send(obj) {
  process.stdout.write(JSON.stringify(obj) + '\n');
}

function updateStatus(status, file, msg) {
  msg = msg ? file + ' ' + msg : file;
  send({ action: 'status', status, msg });
}

function report(file, msg) {
  send({ action: 'report', file, msg });
}

function empty() {}

function stats(name, quantity) {
  quantity = typeof quantity !== 'number' ? 1 : quantity;
  send({ action: 'update', name, quantity });
}

function trimStackTrace(trace) {
  if (!trace) return '';
  const lines = trace.split('\n');
  const result = [];
  const self = __filename;
  for (const line of lines) {
    if (line.indexOf(self) !== -1) break;
    result.push(line);
  }
  return result.join('\n');
}

async function processFiles(files, options) {
  for (const file of files) {
    let source;
    try {
      source = fs.readFileSync(file, 'utf8');
    } catch (err) {
      updateStatus('error', file, 'File error: ' + err);
      continue;
    }
    try {
      const j = prepareJscodeshift(options);
      const out = await transform(
        { path: file, source },
        {
          j,
          jscodeshift: j,
          stats: options.dry ? stats : empty,
          report: (msg) => report(file, msg),
        },
        options
      );
      if (!out || out === source) {
        updateStatus(out ? 'nochange' : 'skip', file);
        continue;
      }
      if (options.print) {
        console.log(out);
      }
      if (!options.dry) {
        try {
          writeFileAtomic.sync(file, out);
          updateStatus('ok', file);
        } catch (err) {
          updateStatus('error', file, 'File writer error: ' + err);
        }
      } else {
        updateStatus('ok', file);
      }
    } catch (err) {
      updateStatus(
        'error',
        file,
        'Transformation error (' +
          String(err.message || err).replace(/\n/g, ' ') +
          ')\n' +
          trimStackTrace(err.stack)
      );
    }
  }
  send({ action: 'free' });
}

// Bootstrap
try {
  setup(transformFile, babelFlag);
} catch (err) {
  send({
    action: 'status',
    status: 'error',
    msg: 'Setup error: ' + (err && err.message ? err.message : String(err)),
  });
  send({ action: 'done' });
  process.exit(1);
